const entry = `\n## 0.5.33\n\n- Made first-contact follow-up an explicit enum setting with Off as the default and absent-setting upgrade behavior.\n- Added exact target-field completion coverage, repaired-warning reconciliation, and stable-ID/omission diagnostics without synthesizing field coverage from group labels.\n- Bounded automatic scans to two provider requests across JSON retries and follow-up, with per-request and aggregate estimated-input diagnostics.\n- Added current-exchange-only dossier “Recheck missing details” using the same locked semantic validation and commit boundary.\n- Consolidated first-scene grounding guidance for habits, durable memories, and remaining live goals; retained bounded profile observations and source de-duplication.\n- Removed the unconditional v0.5.32 completion dispatch and its obsolete tests; persisted tombstones and supported compatibility readers remain unchanged.\n`;
write('CHANGELOG.md', changelog.replace('# Changelog\n', '# Changelog\n' + entry));

